import{_ as t,o as d,c as o,a2 as a}from"./chunks/framework.DrWxItG4.js";const x=JSON.parse('{"title":"World data","description":"","frontmatter":{},"headers":[],"relativePath":"guide/world-data.md","filePath":"guide/world-data.md"}'),r={name:"guide/world-data.md"};function c(s,e,i,n,l,p){return d(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="world-data" tabindex="-1">World data <a class="header-anchor" href="#world-data" aria-label="Permalink to &quot;World data&quot;">​</a></h1><p>The extra data of <a href="/gtps-guide/packets/04-send-map-data">SEND_MAP_DATA (0x04)</a>, as the 5.60 client reads it: <code>World::LoadFromMem</code> (<code>0x15dd348</code>), the tile map loader (<code>0x1620e9c</code>), <code>Tile_Serialize</code> (<code>0x15b0b14</code>) and the dropped-object reader (<code>0x16188d0</code>). The same tile record is used by <a href="/gtps-guide/packets/05-send-tile-update-data">SEND_TILE_UPDATE_DATA (0x05)</a>. Numbers are little-endian; a string is <code>u16 length</code> + bytes. The client calls these readers with a <strong>from server</strong> flag; fields only in its own saved copy of a world (<code>last_world</code>) are noted, and the server never sends them.</p><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>u16   version              world+2. 5.60 knows up to 27; a higher number logs an error but still loads</span></span>
<span class="line"><span>u32   flags                world+0x1a0, logged as &quot;f: %d&quot;; nothing else reads it</span></span>
<span class="line"><span>str   name</span></span>
<span class="line"><span>i32   width, i32 height    tiles</span></span>
<span class="line"><span>u32   tile_count           65026 or more: &quot;Map wants to load %d tiles?&quot; and the load fails</span></span>
<span class="line"><span>5 B   skipped              (from server only)</span></span>
<span class="line"><span>tile_count × tile          row-major: tile (x, y) is entry y*width + x</span></span>
<span class="line"><span>12 B  skipped              (from server only)</span></span>
<span class="line"><span>u32   object_count</span></span>
<span class="line"><span>u32   last_object_uid      the next drop the client creates gets uid ++last_object_uid</span></span>
<span class="line"><span>object_count × object      16 bytes each</span></span>
<span class="line"><span>if version &gt;= 3:</span></span>
<span class="line"><span>  u16 base weather         world+0x1a8 (see OnSetBaseWeather)</span></span>
<span class="line"><span>  u16 terraform type       world+0x1aa (&quot;terraformType&quot;)</span></span>
<span class="line"><span>  u16 current weather      world+0x1ac (see OnSetCurrentWeather)</span></span>
<span class="line"><span>  u16 unknown              world+0x1ae, no reader found</span></span>
<span class="line"><span>  u32 unknown              world+0x1b0, no reader found</span></span>
<span class="line"><span>if version &gt;= 27 (from server only):</span></span>
<span class="line"><span>  u32 unknown              world+0x1a4, no reader found</span></span></code></pre></div><p>After loading, the world name and version are saved as <code>last_world</code> and <code>last_world_version</code>, and <a href="/gtps-guide/functions/OnInitNewWorld">OnInitNewWorld</a> runs (see <a href="/gtps-guide/packets/04-send-map-data">0x04</a>). A few items get <a href="#special-items">fix-ups</a> while loading.</p><p>Version notes:</p><ul><li>Below 3 there is no weather footer at all.</li><li>Above 20 a tile can carry <a href="#tile-components">component data</a>.</li><li>gurotopia sends version 0, so the client logs &quot;Wrong world version&quot; in 0x04 and reads no footer. Its world still loads.</li></ul><h3 id="terraform-type" tabindex="-1">Terraform type <a class="header-anchor" href="#terraform-type" aria-label="Permalink to &quot;Terraform type&quot;">​</a></h3><p><code>world+0x1aa</code> is passed to the client&#39;s script conditions as <code>terraformType</code> (<code>0x1b3076c</code>). The value 25 is special: the client sends its own movement every 100 ms instead of 200 ms (<code>0x1381a2c</code>), and the world screen skips part of its setup (<code>0x1bff3ec</code>, <code>0x13131f8</code>). What kind of world 25 is wasn&#39;t found; it is probably an event world type.</p><h3 id="weather-ids" tabindex="-1">Weather ids <a class="header-anchor" href="#weather-ids" aria-label="Permalink to &quot;Weather ids&quot;">​</a></h3><p>From the client&#39;s <code>WEATHER_TYPE_*</code> table (<code>0xcecca0</code>):</p><p>0 <code>DEFAULT</code>, 1 <code>SUNSET</code>, 2 <code>NIGHT</code>, 3 <code>DESERT</code>, 4 <code>SUNNY</code>, 6 <code>HARVEST</code>, 7 <code>MARS</code>, 8 <code>SPOOKY</code>, 9 <code>MAW</code>, 10 <code>BLANK</code>, 11 <code>SNOWY</code>, 12 <code>GROWCH</code>, 14 <code>UNDERSEA</code>, 15 <code>WARP</code>, 16 <code>COMET</code>, 17 <code>COMET2</code>, 18 <code>PARTY</code>, 19 <code>PINEAPPLE</code>, 21 <code>SPRING</code>, 22 <code>WOLF</code>, 25 <code>FIRE_HAZE</code>, 27 <code>AQUA_HAZE</code>, 28 <code>CUSTOM_HAZE</code>, 29 <code>CUSTOM_ITEMS</code>, 30 <code>PAGODA</code>, 31 <code>APOCALYPSE</code>, 32 <code>JUNGLE</code>, 33 <code>BALLOON_WARZ</code>, 34 <code>BACKGROUND</code>, 35 <code>AUTUMN</code>, 36 <code>HEART</code>, 37 <code>STPATRICKS</code>, 38 <code>ICE_AGE</code>, 39 <code>VOLCANO</code>, 40 <code>FLOATING_ISLANDS</code>, 41 <code>MASCOT</code>, 42 <code>DIGITAL_RAIN</code>, 43 <code>MONOCHROME</code>, 44 <code>TREASURE</code>, 45 <code>SURGERY</code>, 46 <code>BOUNTIFUL</code>, 47 <code>METEOR</code>, 48 <code>STARS</code>, 49 <code>ASCENDED</code>, 50 <code>DESTROYED</code>, 51 <code>GROWTOPIA_SIGN</code>, 52 <code>DUNGEON</code>, 53 <code>LEGENDARY_CITY</code>, 54 <code>BLOOD_DRAGON</code>, 55 <code>POP_CITY</code>, 56 <code>ANZU</code>, 57 <code>TMNT_CITY</code>, 58 <code>RAD_CITY</code>, 59 <code>PLAZA</code>, 60 <code>NEBULA</code>, 61 <code>PROTOSTAR</code>, 62 <code>DARK_MOUNTAINS</code>, 63 <code>AC15</code>, 64 <code>MOUNT_GROWMORE</code>, 65 <code>CRACK_IN_REALITY</code>, 66 <code>LNY_NIAN</code>, 67 <code>RAYMAN_LOCK</code>, 68 <code>STEAMPUNK</code>, 69 <code>REALM_OF_SPIRITS</code>, 70 <code>BLACK_HOLE</code>, 71 <code>GEMS</code>, 72 <code>HOLIDAY_HAVEN</code>, 73 <code>FENYX_LOCK</code>, 74 <code>ENCHANTED_LOCK</code>, 75 <code>ROYAL_ENCHANTED_LOCK</code>, 76 <code>NEPTUNES_ATLANTIS</code>, 77 <code>PINUSKI_PETAL_PURRFECT_HAVEN</code>, 78 <code>CANDY_LAND</code>, 79 <code>DRAGONS_KEEP</code>, 80 <code>EMERALD_CITY</code>, 81 <code>ANCESTRAL_PLANE</code>, 82 <code>BLACK_DIGITAL_RAIN</code>.</p><p>Missing numbers (5, 13, 20, 23, 24, 26) weren&#39;t decoded from the table.</p><h2 id="tile" tabindex="-1">Tile <a class="header-anchor" href="#tile" aria-label="Permalink to &quot;Tile&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>u16 fg                     item id; outside items.dat: &quot;Illegal item %d in %s&quot;, set to 0</span></span>
<span class="line"><span>u16 bg                     item id, same check</span></span>
<span class="line"><span>u16 parent                 tile+0xc0: index (y*width + x) of the lock tile that owns this tile</span></span>
<span class="line"><span>u16 flags                  tile+0x52, see below</span></span>
<span class="line"><span>if flags &amp; 0x02:  u16      replaces parent (tile+0xc0)</span></span>
<span class="line"><span>if flags &amp; 0x01:  u8 extra type + its data   -&gt; Tile extras page, then the common trailer below</span></span>
<span class="line"><span>if version &gt; 20 and fg has a component:  u32 len + len bytes   -&gt; Tile components below</span></span></code></pre></div><p>See <a href="/gtps-guide/guide/tile-extras">Tile extras</a> for each extra type.</p><p>gurotopia writes <code>i16 fg, i16 bg, u8 state[4]</code>: its <code>state</code> is <code>parent</code> and <code>flags</code> as two u16s.</p><h3 id="tile-flags" tabindex="-1">Tile flags <a class="header-anchor" href="#tile-flags" aria-label="Permalink to &quot;Tile flags&quot;">​</a></h3><p>The client&#39;s own names (<code>TILE_FLAG_*</code>, from a table in several static initializers, e.g. <code>0x108ea9c</code>):</p><table tabindex="0"><thead><tr><th>Bit</th><th>Name</th><th>What the client does with it</th></tr></thead><tbody><tr><td><code>0x0001</code></td><td><code>HAS_EXTRA_DATA</code></td><td>a tile extra follows; if the parsed extra turns out empty the flag is cleared</td></tr><tr><td><code>0x0002</code></td><td><code>HAS_PARENT</code></td><td>an extra <code>u16</code> parent index follows</td></tr><tr><td><code>0x0004</code></td><td><code>WAS_SPLICED</code></td><td>the seed&#39;s splice is marked as discovered (<code>0x1483fa0</code>, probably the seed diary)</td></tr><tr><td><code>0x0008</code></td><td><code>WILL_SPAWN_SEEDS_TOO</code></td><td>a tree drops seeds too (<a href="/gtps-guide/packets/0c-send-tile-tree-state">0x0c</a>)</td></tr><tr><td><code>0x0010</code></td><td><code>IS_SEEDLING</code></td><td><a href="/gtps-guide/packets/0c-send-tile-tree-state">0x0c</a></td></tr><tr><td><code>0x0020</code></td><td><code>FLIPPED_X</code></td><td>drawn mirrored</td></tr><tr><td><code>0x0040</code></td><td><code>IS_ON</code></td><td>switched on; for Deathtrap Wall (6154), Prickly Pineapple (8528) and Storm Cloud (7202) a change restarts a timer</td></tr><tr><td><code>0x0080</code></td><td><code>IS_OPEN_TO_PUBLIC</code></td><td></td></tr><tr><td><code>0x0100</code></td><td><code>BG_IS_ON</code></td><td></td></tr><tr><td><code>0x0200</code></td><td><code>FG_ALT_MODE</code></td><td></td></tr><tr><td><code>0x0400</code></td><td><code>IS_WET</code></td><td></td></tr><tr><td><code>0x0800</code></td><td><code>GLUED</code></td><td></td></tr><tr><td><code>0x1000</code></td><td><code>ON_FIRE</code></td><td>counted per world (tilemap+0x10)</td></tr><tr><td><code>0x2000</code></td><td><code>PAINTED_RED</code></td><td></td></tr><tr><td><code>0x4000</code></td><td><code>PAINTED_GREEN</code></td><td></td></tr><tr><td><code>0x8000</code></td><td><code>PAINTED_BLUE</code></td><td>the three paint bits are cleared on lock tiles (action type 3)</td></tr></tbody></table><p>The values of <code>IS_OPEN_TO_PUBLIC</code> and <code>PAINTED_GREEN</code> are inferred from the order of the table and the gaps; the others were read from it.</p><h3 id="which-tiles-have-an-extra" tabindex="-1">Which tiles have an extra <a class="header-anchor" href="#which-tiles-have-an-extra" aria-label="Permalink to &quot;Which tiles have an extra&quot;">​</a></h3><p>The server decides: the client reads an extra whenever flag <code>0x01</code> is set. When the client itself sets a foreground (placing a block), <code>0x15d1014</code> picks the extra type from the item&#39;s action type. The server must send the same type the client would pick, or the client reads the wrong bytes and the rest of the world is garbage. Action types not in this table have no extra.</p><table tabindex="0"><thead><tr><th>Action type</th><th>Client name</th><th>Extra type</th></tr></thead><tbody><tr><td>2</td><td><code>USER_DOOR</code></td><td><a href="/gtps-guide/guide/tile-extras#0x01">0x01</a> Door</td></tr><tr><td>3</td><td><code>LOCK</code></td><td><a href="/gtps-guide/guide/tile-extras#0x03">0x03</a> Lock</td></tr><tr><td>10</td><td><code>SIGN</code></td><td><a href="/gtps-guide/guide/tile-extras#0x02">0x02</a> Sign</td></tr><tr><td>13</td><td><code>DOOR</code></td><td><a href="/gtps-guide/guide/tile-extras#0x01">0x01</a> Door</td></tr><tr><td>15</td><td><code>BEDROCK</code></td><td><a href="/gtps-guide/guide/tile-extras#0x2a">0x2a</a> Data Bedrock</td></tr><tr><td>19</td><td><code>SEED</code></td><td><a href="/gtps-guide/guide/tile-extras#0x04">0x04</a> Seed</td></tr><tr><td>26</td><td><code>PORTAL</code></td><td><a href="/gtps-guide/guide/tile-extras#0x01">0x01</a> Door</td></tr><tr><td>30</td><td><code>RACE_FLAG</code></td><td><a href="/gtps-guide/guide/tile-extras#0x05">0x05</a> (no data)</td></tr><tr><td>33</td><td><code>MAILBOX</code></td><td><a href="/gtps-guide/guide/tile-extras#0x06">0x06</a> Mailbox</td></tr><tr><td>34</td><td><code>BULLETIN</code></td><td><a href="/gtps-guide/guide/tile-extras#0x07">0x07</a> Bulletin board</td></tr><tr><td>36</td><td><code>DICE</code></td><td><a href="/gtps-guide/guide/tile-extras#0x08">0x08</a> Dice block</td></tr><tr><td>38</td><td><code>PROVIDER</code></td><td><a href="/gtps-guide/guide/tile-extras#0x09">0x09</a> Provider</td></tr><tr><td>40</td><td><code>ACHIEVEMENT</code></td><td><a href="/gtps-guide/guide/tile-extras#0x0a">0x0a</a> Achievement block</td></tr><tr><td>43</td><td><code>SUNGATE</code></td><td><a href="/gtps-guide/guide/tile-extras#0x01">0x01</a> Door</td></tr><tr><td>46</td><td><code>HEART_MONITOR</code></td><td><a href="/gtps-guide/guide/tile-extras#0x0b">0x0b</a> Heart monitor</td></tr><tr><td>47</td><td><code>DONATION_BOX</code></td><td><a href="/gtps-guide/guide/tile-extras#0x0c">0x0c</a> Donation box</td></tr><tr><td>48</td><td><code>TOYBOX</code></td><td><a href="/gtps-guide/guide/tile-extras#0x0d">0x0d</a> (mailbox layout)</td></tr><tr><td>49</td><td><code>MANNEQUIN</code></td><td><a href="/gtps-guide/guide/tile-extras#0x0e">0x0e</a> Mannequin</td></tr><tr><td>50</td><td><code>CAMERA</code></td><td><a href="/gtps-guide/guide/tile-extras#0x07">0x07</a> Bulletin board</td></tr><tr><td>51</td><td><code>MAGICEGG</code></td><td><a href="/gtps-guide/guide/tile-extras#0x0f">0x0f</a> Bunny egg</td></tr><tr><td>52</td><td><code>TEAM</code></td><td><a href="/gtps-guide/guide/tile-extras#0x10">0x10</a> Game block</td></tr><tr><td>53</td><td><code>GAME_GEN</code></td><td><a href="/gtps-guide/guide/tile-extras#0x11">0x11</a> Game generator</td></tr><tr><td>54</td><td><code>XENONITE</code></td><td><a href="/gtps-guide/guide/tile-extras#0x12">0x12</a> Xenonite crystal</td></tr><tr><td>55</td><td><code>DRESSUP</code></td><td><a href="/gtps-guide/guide/tile-extras#0x13">0x13</a> Phone booth</td></tr><tr><td>56</td><td><code>CRYSTAL</code></td><td><a href="/gtps-guide/guide/tile-extras#0x14">0x14</a> Crystal</td></tr><tr><td>57</td><td><code>BURGLAR</code></td><td><a href="/gtps-guide/guide/tile-extras#0x15">0x15</a> Crime in progress</td></tr><tr><td>59</td><td><code>SPOTLIGHT</code></td><td><a href="/gtps-guide/guide/tile-extras#0x16">0x16</a> Spotlight</td></tr><tr><td>61</td><td><code>DISPLAY_BLOCK</code></td><td><a href="/gtps-guide/guide/tile-extras#0x17">0x17</a> Display block</td></tr><tr><td>62</td><td><code>VENDING</code></td><td><a href="/gtps-guide/guide/tile-extras#0x18">0x18</a> Vending machine</td></tr><tr><td>63</td><td><code>FISHTANK</code></td><td><a href="/gtps-guide/guide/tile-extras#0x19">0x19</a> Fish tank port</td></tr><tr><td>65</td><td><code>SOLAR</code></td><td><a href="/gtps-guide/guide/tile-extras#0x1a">0x1a</a> Solar collector</td></tr><tr><td>66</td><td><code>FORGE</code></td><td><a href="/gtps-guide/guide/tile-extras#0x1b">0x1b</a> Forge</td></tr><tr><td>67</td><td><code>GIVING_TREE</code></td><td><a href="/gtps-guide/guide/tile-extras#0x1c">0x1c</a> Giving Tree</td></tr><tr><td>68</td><td><code>GIVING_TREE_STUMP</code></td><td><a href="/gtps-guide/guide/tile-extras#0x1d">0x1d</a> Giving Tree Stump</td></tr><tr><td>71</td><td><code>STEAM_ORGAN</code></td><td><a href="/gtps-guide/guide/tile-extras#0x1e">0x1e</a> Steam Organ</td></tr><tr><td>72</td><td><code>TAMAGOTCHI</code></td><td><a href="/gtps-guide/guide/tile-extras#0x1f">0x1f</a> Silkworm</td></tr><tr><td>73</td><td><code>SEWING</code></td><td><a href="/gtps-guide/guide/tile-extras#0x20">0x20</a> Sewing Machine</td></tr><tr><td>74</td><td><code>FLAG</code></td><td><a href="/gtps-guide/guide/tile-extras#0x21">0x21</a> Country Flag / Challenge flags</td></tr><tr><td>75</td><td><code>LOBSTER_TRAP</code></td><td><a href="/gtps-guide/guide/tile-extras#0x22">0x22</a> Lobster Trap</td></tr><tr><td>76</td><td><code>ARTCANVAS</code></td><td><a href="/gtps-guide/guide/tile-extras#0x23">0x23</a> Painting Easel</td></tr><tr><td>77</td><td><code>BATTLE_CAGE</code></td><td><a href="/gtps-guide/guide/tile-extras#0x24">0x24</a> Battle Pet Cage</td></tr><tr><td>78</td><td><code>PET_TRAINER</code></td><td><a href="/gtps-guide/guide/tile-extras#0x25">0x25</a> Pet Trainer</td></tr><tr><td>79</td><td><code>STEAM_ENGINE</code></td><td><a href="/gtps-guide/guide/tile-extras#0x26">0x26</a> Steam Engine</td></tr><tr><td>80</td><td><code>LOCK_BOT</code></td><td><a href="/gtps-guide/guide/tile-extras#0x27">0x27</a> Lock-Bot</td></tr><tr><td>81</td><td><code>WEATHER_SPECIAL</code></td><td><a href="/gtps-guide/guide/tile-extras#0x28">0x28</a> Weather Machine (one setting)</td></tr><tr><td>82</td><td><code>SPIRIT_STORAGE</code></td><td><a href="/gtps-guide/guide/tile-extras#0x29">0x29</a> Spirit Storage Unit</td></tr><tr><td>83</td><td><code>DISPLAY_SHELF</code></td><td><a href="/gtps-guide/guide/tile-extras#0x2b">0x2b</a> Display Shelf</td></tr><tr><td>84</td><td><code>VIP_DOOR</code></td><td><a href="/gtps-guide/guide/tile-extras#0x2c">0x2c</a> VIP Entrance</td></tr><tr><td>85</td><td><code>CHAL_TIMER</code></td><td><a href="/gtps-guide/guide/tile-extras#0x2d">0x2d</a> Challenge Timer</td></tr><tr><td>86</td><td><code>CHAL_FLAG</code></td><td><a href="/gtps-guide/guide/tile-extras#0x21">0x21</a> Country Flag / Challenge flags</td></tr><tr><td>87</td><td><code>FISH_MOUNT</code></td><td><a href="/gtps-guide/guide/tile-extras#0x2f">0x2f</a> Fish Wall Mount</td></tr><tr><td>88</td><td><code>PORTRAIT</code></td><td><a href="/gtps-guide/guide/tile-extras#0x30">0x30</a> Portrait</td></tr><tr><td>89</td><td><code>WEATHER_SPECIAL2</code></td><td><a href="/gtps-guide/guide/tile-extras#0x31">0x31</a> Weather Machine (several settings)</td></tr><tr><td>91</td><td><code>FOSSIL_PREP</code></td><td><a href="/gtps-guide/guide/tile-extras#0x32">0x32</a> Fossil Prep Station</td></tr><tr><td>92</td><td><code>DNA_MACHINE</code></td><td><a href="/gtps-guide/guide/tile-extras#0x33">0x33</a> DNA Processor</td></tr><tr><td>93</td><td><code>BLASTER</code></td><td><a href="/gtps-guide/guide/tile-extras#0x34">0x34</a> Howler / Trickster</td></tr><tr><td>96</td><td><code>CHEMTANK</code></td><td><a href="/gtps-guide/guide/tile-extras#0x35">0x35</a> Chemsynth Tank</td></tr><tr><td>97</td><td><code>STORAGE</code></td><td><a href="/gtps-guide/guide/tile-extras#0x36">0x36</a> Storage box</td></tr><tr><td>98</td><td><code>OVEN</code></td><td><a href="/gtps-guide/guide/tile-extras#0x37">0x37</a> Oven</td></tr><tr><td>99</td><td><code>SUPER_MUSIC</code></td><td><a href="/gtps-guide/guide/tile-extras#0x38">0x38</a> Audio Rack</td></tr><tr><td>100</td><td><code>GEIGERCHARGE</code></td><td><a href="/gtps-guide/guide/tile-extras#0x39">0x39</a> Geiger Charger</td></tr><tr><td>101</td><td><code>ADVENTURE_RESET</code></td><td><a href="/gtps-guide/guide/tile-extras#0x3a">0x3a</a> Adventure Begins</td></tr><tr><td>102</td><td><code>TOMB_ROBBER</code></td><td><a href="/gtps-guide/guide/tile-extras#0x3b">0x3b</a> Tomb Robber</td></tr><tr><td>103</td><td><code>FACTION</code></td><td><a href="/gtps-guide/guide/tile-extras#0x3c">0x3c</a> Faction block</td></tr><tr><td>104</td><td><code>RED_FACTION</code></td><td><a href="/gtps-guide/guide/tile-extras#0x3c">0x3c</a> Faction block</td></tr><tr><td>105</td><td><code>GREEN_FACTION</code></td><td><a href="/gtps-guide/guide/tile-extras#0x3c">0x3c</a> Faction block</td></tr><tr><td>106</td><td><code>BLUE_FACTION</code></td><td><a href="/gtps-guide/guide/tile-extras#0x3c">0x3c</a> Faction block</td></tr><tr><td>109</td><td><code>FISHGOTCHI_TANK</code></td><td><a href="/gtps-guide/guide/tile-extras#0x3d">0x3d</a> Training Port</td></tr><tr><td>111</td><td><code>ITEM_SUCKER</code></td><td><a href="/gtps-guide/guide/tile-extras#0x3e">0x3e</a> Item Sucker (MAGPLANT)</td></tr><tr><td>113</td><td><code>ROBOT</code></td><td><a href="/gtps-guide/guide/tile-extras#0x3f">0x3f</a> Robot</td></tr><tr><td>115</td><td><code>LUCKY_TICKET</code></td><td><a href="/gtps-guide/guide/tile-extras#0x40">0x40</a> Lucky Token</td></tr><tr><td>116</td><td><code>STATS_BLOCK</code></td><td><a href="/gtps-guide/guide/tile-extras#0x42">0x42</a> GrowScan 9000</td></tr><tr><td>117</td><td><code>FIELD_NODE</code></td><td><a href="/gtps-guide/guide/tile-extras#0x43">0x43</a> Containment Field Power Node</td></tr><tr><td>118</td><td><code>OUIJA_BOARD</code></td><td><a href="/gtps-guide/guide/tile-extras#0x44">0x44</a> Spirit Board</td></tr><tr><td>123</td><td><code>AUTO_ACTION_BREAK</code></td><td><a href="/gtps-guide/guide/tile-extras#0x45">0x45</a> Tesseract Manipulator</td></tr><tr><td>124</td><td><code>AUTO_ACTION_HARVEST</code></td><td><a href="/gtps-guide/guide/tile-extras#0x46">0x46</a> Heart of Gaia</td></tr><tr><td>125</td><td><code>AUTO_ACTION_HARVEST_SUCK</code></td><td><a href="/gtps-guide/guide/tile-extras#0x47">0x47</a> Techno-Organic Engine</td></tr><tr><td>126</td><td><code>LIGHTNING_CLOUD</code></td><td><a href="/gtps-guide/guide/tile-extras#0x48">0x48</a> Storm Cloud</td></tr><tr><td>127</td><td><code>PHASED_BLOCK</code></td><td><a href="/gtps-guide/guide/tile-extras#0x49">0x49</a> Phased block</td></tr><tr><td>130</td><td><code>PASSWORD_STORAGE</code></td><td><a href="/gtps-guide/guide/tile-extras#0x4a">0x4a</a> Safe Vault</td></tr><tr><td>131</td><td><code>PHASED_BLOCK_2</code></td><td><a href="/gtps-guide/guide/tile-extras#0x4b">0x4b</a> Angelic Counting Cloud</td></tr><tr><td>133</td><td><code>PVE_NPC</code></td><td><a href="/gtps-guide/guide/tile-extras#0x4c">0x4c</a> PvE NPC</td></tr><tr><td>134</td><td><code>INFINITY_WEATHER_MACHINE</code></td><td><a href="/gtps-guide/guide/tile-extras#0x4d">0x4d</a> Infinity Weather Machine</td></tr><tr><td>137</td><td><code>COMPLETIONIST</code></td><td><a href="/gtps-guide/guide/tile-extras#0x4e">0x4e</a> Completionist</td></tr><tr><td>140</td><td><code>FEEDING_BLOCK</code></td><td><a href="/gtps-guide/guide/tile-extras#0x4f">0x4f</a> Feeding block</td></tr><tr><td>141</td><td><code>KRANKENS_BLOCK</code></td><td><a href="/gtps-guide/guide/tile-extras#0x50">0x50</a> Kranken&#39;s block</td></tr><tr><td>142</td><td><code>FRIENDS_ENTRANCE</code></td><td><a href="/gtps-guide/guide/tile-extras#0x51">0x51</a> Friends Entrance</td></tr></tbody></table><p>Action type names are the client&#39;s <code>ITEM_TYPE_*</code> names; see <a href="/gtps-guide/guide/items-dat#action-types">items.dat</a>.</p><h3 id="common-trailer" tabindex="-1">Common trailer <a class="header-anchor" href="#common-trailer" aria-label="Permalink to &quot;Common trailer&quot;">​</a></h3><p>After an extra&#39;s own bytes, <code>TileExtra_Serialize</code> (<code>0x15ce080</code>, label <code>0x15d04a8</code>) reads more bytes for two kinds of foreground:</p><ul><li><p><strong>Guild items</strong> (items.dat flag <code>GUILD_ITEM</code>, <code>flags2 &amp; 0x200</code>; 67 items in 5.60: the Guild Lock (5814), Guild Key, entrances, banners, flag poles and flags):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>u8   unknown            extra+9; not present for the Guild Lock itself (5814)</span></span>
<span class="line"><span>u32  probably the guild id                          extra+0xe0</span></span>
<span class="line"><span>u32  guild emblem: low 16 bits the foreground item, high 16 bits the background item (0 = none)  extra+0xe4</span></span>
<span class="line"><span>u32  guild level                                     extra+0xe8</span></span>
<span class="line"><span>u32  must be non-zero for the emblem to be drawn    extra+0xec</span></span></code></pre></div><p>The drawing code (<code>0x11b4230</code>) uses <code>+0xe8</code> for the Guild Lock&#39;s frame (4, 5 above level 5, one more above 10) and its flag overlay (<code>level % 5</code>). It draws the emblem items only when <code>+0xe4</code> and <code>+0xec</code> are both non-zero.</p></li><li><p><strong>Data Starship Hull (6546)</strong> in worlds of version 5 or newer, when it isn&#39;t a guild item:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>6 × u32                 extra+0xf0, +0xf8, +0xf4, +0x104, +0xfc, +0x100</span></span>
<span class="line"><span>u64                     extra+0x130, version 11+, saved copy only (not sent by the server)</span></span>
<span class="line"><span>u32                     extra+0x110, version 15+</span></span></code></pre></div></li><li><p>Any tile whose extra type is <code>0x2a</code> (<code>&#39;*&#39;</code>, Data Bedrock) in version 11+: a <code>u64</code> (extra+0x130), saved copy only.</p></li></ul><p>What the starship values mean wasn&#39;t traced.</p><h2 id="tile-components" tabindex="-1">Tile components <a class="header-anchor" href="#tile-components" aria-label="Permalink to &quot;Tile components&quot;">​</a></h2><p>From version 21 a tile can also carry a <strong>component</strong>: a <code>u32</code> length followed by that many bytes of <a href="https://cbor.io/" target="_blank" rel="noreferrer">CBOR</a>-encoded JSON (<code>nlohmann::json::from_cbor</code>, <code>0x15b15f8</code>). The client creates the component from the foreground item (<code>0x145a0bc</code>) and only reads the bytes if the item has one. A length of 0 removes it. If the world&#39;s version is below the component&#39;s minimum, no bytes are read.</p><table tabindex="0"><thead><tr><th>Item</th><th>Component (RTTI name)</th><th>Min version</th><th>Sent by server</th><th>JSON keys</th></tr></thead><tbody><tr><td>Battle Pet Cage (3548)</td><td><code>BattleCageData</code></td><td>24</td><td>yes</td><td><code>pet</code> (3 numbers), <code>damage</code></td></tr><tr><td>Offering Table (12598)</td><td><code>OfferingTableData</code></td><td>0</td><td><strong>no</strong> (saved copy only)</td><td><code>itemsInSlots</code>, <code>lastReward</code>, <code>lastRewardCount</code></td></tr><tr><td>Operating Table (14662)</td><td><code>OperatingTableData</code></td><td>0</td><td>yes</td><td><code>isInSurgery</code> (bool), <code>currentState</code>, <code>nextSwitchAt</code></td></tr><tr><td>Auto Surgeon Station (14666)</td><td><code>AutoSurgeonStationData</code></td><td>0</td><td>yes</td><td><code>outOfOrder</code>, <code>wlCount</code>, <code>selectedIllness</code>, <code>stockedItems</code>, <code>lastUpdateTime</code>, <code>wlCost</code>, <code>disabled</code></td></tr><tr><td>Reception Desk (14668)</td><td><code>ReceptionDeskData</code></td><td>0</td><td><strong>no</strong> (saved copy only)</td><td><code>HL</code>, <code>CI</code>, <code>TS</code>, <code>SS</code>, <code>DL</code>, <code>IC</code></td></tr><tr><td>Party Projector (15376)</td><td><code>PartyProjectorData</code></td><td>0</td><td>yes</td><td><code>MovementSpeed</code>, <code>SpinningSpeed</code> (floats), <code>SelectedPatternID</code></td></tr><tr><td>Auction Block (15546)</td><td><code>AuctionBlockData</code></td><td>0</td><td>yes</td><td><code>Item</code>, <code>DurationHrs</code>, <code>StartingPrice</code>, <code>State</code>, <code>EndTime</code> (64-bit)</td></tr><tr><td>Weather Machine - Concert Lights (16094)</td><td><code>WeatherMachineData</code></td><td>0</td><td>yes</td><td><code>jsonString</code> (a string)</td></tr><tr><td>Bountiful roots: 8624, 8630, ... 8714 (every 6th id, 16 items)</td><td><code>RootsData</code></td><td>25</td><td>yes</td><td><code>IsGreyRoot</code> (bool), <code>RootLevel</code> (0–3, larger becomes 0)</td></tr></tbody></table><p>&quot;Sent by server: no&quot; means the component&#39;s <code>+0x20</code> method returns true, and the client then skips it when reading from the server: send no length for those items. A missing key reads as 0/false.</p><p>Before version 24 a Battle Pet Cage&#39;s data is converted from its tile extra, and before 25 a root&#39;s from its flags (<code>IsGreyRoot</code> = <code>IS_ON</code> clear; <code>RootLevel</code> from bits <code>0x20</code> and <code>0x200</code>). This only happens for the saved copy.</p><h2 id="dropped-object" tabindex="-1">Dropped object <a class="header-anchor" href="#dropped-object" aria-label="Permalink to &quot;Dropped object&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>u16 item id          not in items.dat -&gt; becomes 2 (Dirt)</span></span>
<span class="line"><span>f32 x, f32 y         pixels</span></span>
<span class="line"><span>u8  count</span></span>
<span class="line"><span>u8  flags            object+0xb; meaning not traced</span></span>
<span class="line"><span>u32 uid</span></span></code></pre></div><p>gurotopia writes <code>i16 id, f32 x, f32 y, i16 count, i32 uid</code>, which is the same bytes when count &lt; 256 and the flags byte is 0.</p><h2 id="special-items" tabindex="-1">Special items <a class="header-anchor" href="#special-items" aria-label="Permalink to &quot;Special items&quot;">​</a></h2><p>These only apply when the client loads its own saved copy (not from the server):</p><ul><li>Busted Game Block (1620), Missing Game Flag (1624) and Missing Game Egg (5994) are read as Game Block (1618), Game Flag (1622) and Game Egg (5992).</li><li>Locke The Salesman (2398) is removed.</li><li>Surg-E (4296) and the Chemsynth Processor/Tank (4430, 4432) are switched off (<code>IS_ON</code> cleared).</li><li>A Dice Block (456) in a version-0 world is removed (&quot;Found dice, removing&quot;).</li></ul><p>From the server, a Containment Field Power Node (6084) that is replaced by another item runs the field-removal code (<code>0x15e09a0</code>).</p><p><small>Readers: <code>0x15dd348</code>, <code>0x1620e9c</code>, <code>0x15b0b14</code>, <code>0x15b1144</code>, <code>0x145a0bc</code>, <code>0x15b15f8</code>, <code>0x16188d0</code>, <code>0x161493c</code>; trailer: <code>0x15ce080</code>; type table: <code>0x15d1014</code>.</small></p>`,42)])])}const h=t(r,[["render",c]]);export{x as __pageData,h as default};
